const GRAPH = $('Eingabe vorbereiten').first().json.graph;

/* ============================================================
   Routing für den n8n-Code-Node (Modus: "Run Once for All Items")
   GRAPH und Synonyme kommen aus dem Node "Eingabe vorbereiten" (graph.json, raum-synonyme.json).
   Routing-Kern aus n8n-routing-code-haus.js, ergänzt um Anzeigenamen aus den Synonymen.

   Eingabe (ein Item), alle Felder optional:
     ziel_typ   "toilette" | "treppe" | "fahrstuhl" | "eingang" | "hoersaal"
     ziel_raum  "03.03.21" (Haus.Etage.Raum, eindeutig) oder "03.21" (Haus.Raum, nächstgelegener)
     ziel_id    exakte Knoten-ID, z. B. "03.03.25"
     start_id   exakte Knoten-ID als Startpunkt
     x, y       Position in Metern (Plan-Koordinaten), etage: Etagen-Nummer, haus: Hausnummer
     barrierefrei  true = Wege mit Stufen und Treppen meiden
   Ohne Start: Position (x, y) wenn vorhanden, sonst der erste Eingang im Graphen.

   Ausgabe: { ok, start, ziel, gesamt_m, schritte[], text, pfad[] }
   ============================================================ */

const TUER_TYPEN = ['raum', 'hoersaal', 'toilette'];
const MERKMAL_TYPEN = ['raum', 'hoersaal', 'toilette', 'treppe', 'fahrstuhl'];
const TYP_ALIASE = {
  toilette: 'toilette', toiletten: 'toilette', wc: 'toilette', klo: 'toilette',
  treppe: 'treppe', treppen: 'treppe', treppenhaus: 'treppe',
  fahrstuhl: 'fahrstuhl', aufzug: 'fahrstuhl', lift: 'fahrstuhl',
  eingang: 'eingang', ausgang: 'eingang', haupteingang: 'eingang',
  hoersaal: 'hoersaal', horsaal: 'hoersaal'
};
// Eigene Begriffe auf Raumnummern abbilden, z. B. { sekretariat: '03.01' }
const ALIASE = (($('Eingabe vorbereiten').first().json.synonyme) || {}).aliase || {};
const WINKEL_GERADE = 35;   // Grad: kleiner = geradeaus
const STUFEN_ZUSCHLAG_M = 2; // pro Stufe als Umweg-Äquivalent bei der Wegsuche (Anzeige bleibt in echten Metern)

const norm = s => String(s == null ? '' : s).toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/ß/g, 'ss')
  .replace(/[^a-z0-9]/g, '');
const pad2 = s => String(s).padStart(2, '0');
const rest = n => n.id.replace(/^\d{2}\.\d{2}\./, '');   // 03.03.25 -> 25, 03.03.Toilette2 -> Toilette2

// "03.03.21" (Haus.Etage.Raum) -> { haus: "03", etage: 3, raum: "21" }
// "03.21" (Haus.Raum)         -> { haus: "03", etage: null, raum: "21" }
function parseCode(s) {
  const a = ALIASE[norm(s)];
  if (a) s = a;
  const m = String(s || '').match(/(\d{1,2})\s*[.\-,]\s*(\d{1,2})(?:\s*[.\-,]\s*(\d{1,2}))?/);
  if (!m) return null;
  if (m[3]) return { haus: pad2(m[1]), etage: Number(m[2]), raum: pad2(m[3]) };
  return { haus: pad2(m[1]), etage: null, raum: pad2(m[2]) };
}
// 03.03.25 -> ["25"]; 03.03.05/06/08 -> ["05","06","08"]; 03.03.33/1 -> ["33"]
function raumCodes(n) {
  const m = rest(n).match(/^(\d{2})((?:\/\d{2})*)(?:\/\d)?$/);
  if (!m) return [];
  const extra = m[2] ? m[2].split('/').filter(Boolean) : [];
  return [m[1], ...extra];
}
const zahl = s => { const m = String(s).match(/\d+/); return m ? ' ' + m[0] : ''; };
// Anzeigenamen aus raum-synonyme.json (erste Bezeichnung), Raumnummer ohne Tür-Suffix (/1, /2)
const NAMEN = new Map();
for (const e of ((($('Eingabe vorbereiten').first().json.synonyme) || {}).ziele || [])) for (const id of e.knoten_ids) { if (!NAMEN.has(id)) NAMEN.set(id, e.bezeichnung || e.namen[0]); }
function label(n) {
  if (n.name && n.name !== n.id) return n.name;
  const basisId = n.id.replace(/\/\d+$/, '');
  if (NAMEN.has(n.id)) return NAMEN.get(n.id) + ' (' + basisId + ')';
  switch (n.typ) {
    case 'raum': case 'hoersaal': return 'Raum ' + basisId;
    case 'toilette': return 'Toilette' + zahl(rest(n));
    case 'treppe': return 'Treppenhaus' + zahl(rest(n));
    case 'fahrstuhl': return 'Aufzug' + zahl(rest(n));
    case 'uebergang': return 'Übergang';
    case 'eingang': return 'Eingang';
    default: return n.id;
  }
}
// y zeigt nach unten (Plan): positives Kreuzprodukt = Rechtsdrehung
function drehung(d1, d2) {
  const cross = d1.x * d2.y - d1.y * d2.x;
  const dot = d1.x * d2.x + d1.y * d2.y;
  const w = Math.atan2(cross, dot) * 180 / Math.PI;
  if (Math.abs(w) < WINKEL_GERADE) return 'geradeaus';
  if (Math.abs(w) > 150) return 'umkehren';
  return w > 0 ? 'rechts' : 'links';
}
const meterText = m => String(Math.max(1, Math.round(m * 2) / 2)).replace('.', ',');
const vec = (a, b) => ({ x: b.x - a.x, y: b.y - a.y });

function route(G, q) {
  q = q || {};
  const nodes = new Map(G.knoten.map(n => [n.id, n]));
  const adj = new Map(G.knoten.map(n => [n.id, []]));
  const bf = q.barrierefrei === true || q.barrierefrei === 'true' || q.barrierefrei === 1 || q.barrierefrei === '1';
  for (const k of G.kanten) {
    if (!nodes.has(k.von) || !nodes.has(k.nach)) continue;
    const stufen = Number(k.stufen) || 0;
    if (bf && (stufen > 0 || nodes.get(k.von).typ === 'treppe' || nodes.get(k.nach).typ === 'treppe')) continue;
    const e = { w: k.laenge_m, wechsel: !!k.etagenwechsel, stufen, cost: k.laenge_m + stufen * STUFEN_ZUSCHLAG_M };
    adj.get(k.von).push({ to: k.nach, ...e });
    adj.get(k.nach).push({ to: k.von, ...e });
  }

  /* ---- Start ---- */
  const x = q.x == null || q.x === '' ? NaN : Number(q.x);
  const y = q.y == null || q.y === '' ? NaN : Number(q.y);
  const etage = q.etage == null || q.etage === '' ? NaN : Number(q.etage);
  const haus = q.haus == null || q.haus === '' ? null : pad2(q.haus);
  let start = null;
  if (q.start_id && nodes.has(q.start_id)) start = nodes.get(q.start_id);
  else {
    const pool = G.knoten.filter(n => (Number.isNaN(etage) || n.etage === etage) && (!haus || n.haus === haus));
    if (Number.isFinite(x) && Number.isFinite(y) && pool.length) {
      let bd = Infinity;
      for (const n of pool) { const d = Math.hypot(n.x - x, n.y - y); if (d < bd) { bd = d; start = n; } }
    } else start = pool.find(n => n.typ === 'eingang') || G.knoten.find(n => n.typ === 'eingang') || null;
  }
  if (!start) return { ok: false, fehler: 'start_unbekannt', hinweis: 'Kein Startpunkt gefunden.' };

  /* ---- Ziel(e) ---- */
  let cand = [];
  if (q.ziel_id && nodes.has(q.ziel_id)) cand = [nodes.get(q.ziel_id)];
  else if (q.ziel_raum) {
    const p = parseCode(q.ziel_raum);
    if (p) cand = G.knoten.filter(n => n.haus === p.haus && raumCodes(n).includes(p.raum) && (p.etage == null || n.etage === p.etage));
  } else if (q.ziel_typ) {
    const t = norm(q.ziel_typ);
    let typ = TYP_ALIASE[t];
    if (!typ) { const k = Object.keys(TYP_ALIASE).find(k => t.includes(k)); typ = k && TYP_ALIASE[k]; }
    if (typ) {
      const ids = new Set((($('Eingabe vorbereiten').first().json.synonyme || {}).ziele || [])
        .filter(e => e.kategorie === typ).flatMap(e => e.knoten_ids));
      cand = G.knoten.filter(n => n.typ === typ || (typ === 'hoersaal' && ids.has(n.id)));
    }
  }
  if (!cand.length) return { ok: false, fehler: 'ziel_unbekannt', hinweis: 'Das Ziel ist im Plan nicht vorhanden oder nicht eindeutig genannt.' };
  if (cand.some(n => n.id === start.id)) return { ok: true, start: info(start), ziel: info(start), gesamt_m: 0, stufen_gesamt: 0, barrierefrei: bf, schritte: [], text: 'Du bist bereits am Ziel.', pfad: [] };

  /* ---- Dijkstra (reicht für einige hundert Knoten) ---- */
  const dist = new Map(), prev = new Map(), done = new Set();
  for (const id of nodes.keys()) dist.set(id, Infinity);
  dist.set(start.id, 0);
  for (;;) {
    let u = null, best = Infinity;
    for (const [id, d] of dist) if (!done.has(id) && d < best) { best = d; u = id; }
    if (u === null) break;
    done.add(u);
    for (const e of adj.get(u)) {
      const nd = best + e.cost;
      if (nd < dist.get(e.to)) { dist.set(e.to, nd); prev.set(e.to, { from: u, e }); }
    }
  }
  let target = null;
  for (const n of cand) if (dist.get(n.id) < Infinity && (!target || dist.get(n.id) < dist.get(target.id))) target = n;
  if (!target) return { ok: false, fehler: 'kein_weg', hinweis: bf ? 'Ohne Stufen und Treppen gibt es keinen Weg zum Ziel.' : 'Zwischen Start und Ziel gibt es keinen Weg im Graphen.' };

  /* ---- Pfad ---- */
  const idsRev = [target.id], esRev = [];
  for (let c = target.id; c !== start.id;) { const p = prev.get(c); esRev.push(p.e); c = p.from; idsRev.push(c); }
  const ids = idsRev.reverse(), es = esRev.reverse();
  const P = ids.map(id => nodes.get(id));
  const inPath = new Set(ids);

  // Ecken: dort wird abgebogen, Türen daneben werden nicht als "vorbei" genannt
  const ecke = P.map(() => false);
  for (let i = 1; i < P.length - 1; i++) {
    ecke[i] = es[i - 1].wechsel || es[i].wechsel || drehung(vec(P[i - 1], P[i]), vec(P[i], P[i + 1])) !== 'geradeaus';
  }

  /* ---- Schritte (Abbiegen per Code) ---- */
  const steps = [];
  let heading = null, leg = null, zielGesetzt = false;
  const neuesLeg = () => ({ meter: 0, vorbei: [], durch: [] });
  const flush = () => {
    if (leg && leg.meter > 0) steps.push({ aktion: 'gehen', meter: leg.meter, vorbei: pick(leg.vorbei), durch: leg.durch });
    leg = null;
  };
  let i = 0;
  if (TUER_TYPEN.includes(start.typ) && P.length > 1 && !es[0].wechsel) {
    steps.push({ aktion: 'verlassen', meter: es[0].w });
    heading = vec(P[0], P[1]);
    i = 1;
  }
  for (; i < P.length - 1; i++) {
    const a = P[i], b = P[i + 1], e = es[i], d = vec(a, b);
    if (e.wechsel) {
      flush();
      if (a.haus !== b.haus) steps.push({ aktion: 'haus', nach_haus: b.haus, meter: e.w });
      else steps.push({ aktion: 'etage', mittel: a.typ, nach_etage: b.etage, meter: e.w });
      heading = null; continue;
    }
    // Letzte Kante in eine Abzweigung (Tür, Treppe, Fahrstuhl): "Ziel liegt links/rechts"
    if (i === P.length - 2 && MERKMAL_TYPEN.includes(b.typ) && heading) {
      const t = drehung(heading, d);
      if (t !== 'geradeaus') {
        flush();
        steps.push({ aktion: 'ziel', seite: t, meter: e.w });
        zielGesetzt = true;
        break;
      }
    }
    if (heading) {
      const t = drehung(heading, d);
      if (t !== 'geradeaus') { flush(); steps.push({ aktion: t }); }
    }
    if (e.stufen > 0) {
      flush();
      steps.push({ aktion: 'stufen', anzahl: e.stufen, meter: e.w });
      heading = d; continue;
    }
    if (!leg) leg = neuesLeg();
    leg.meter += e.w;
    heading = d;
    if (i + 1 < P.length - 1) {
      if (TUER_TYPEN.includes(b.typ)) leg.durch.push(label(b));
      if (!ecke[i + 1]) {
        for (const nb of adj.get(b.id)) {
          if (inPath.has(nb.to) || nb.wechsel) continue;
          const n = nodes.get(nb.to);
          if (!MERKMAL_TYPEN.includes(n.typ)) continue;
          const v = vec(b, n), cr = d.x * v.y - d.y * v.x;
          const nrm = Math.hypot(d.x, d.y) * Math.hypot(v.x, v.y);
          if (!nrm || Math.abs(cr) / nrm < 0.3) continue;
          leg.vorbei.push({ name: label(n), seite: cr > 0 ? 'rechts' : 'links' });
        }
      }
    }
  }
  if (!zielGesetzt) { flush(); steps.push({ aktion: 'ziel', seite: null }); }

  /* ---- Texte ---- */
  const zl = label(target);
  const seiteText = { geradeaus: 'geradeaus', links: 'links', rechts: 'rechts', umkehren: 'hinter dir' };
  steps.forEach((s, k) => {
    s.nr = k + 1;
    if (s.aktion === 'verlassen') s.text = 'Verlasse den Raum.';
    else if (s.aktion === 'gehen') {
      s.text = 'Gehe ' + meterText(s.meter) + ' m geradeaus'
        + (s.durch.length ? ' (durch ' + s.durch.join(', ') + ')' : '')
        + (s.vorbei.length ? ' (vorbei an ' + s.vorbei.map(v => v.name + ' ' + v.seite).join(', ') + ')' : '') + '.';
    }
    else if (s.aktion === 'links' || s.aktion === 'rechts') s.text = 'Biege ' + s.aktion + ' ab.';
    else if (s.aktion === 'umkehren') s.text = 'Drehe um.';
    else if (s.aktion === 'haus') s.text = 'Gehe durch den Übergang in Haus ' + s.nach_haus + '.';
    else if (s.aktion === 'stufen') s.text = 'Es folgen ' + s.anzahl + (s.anzahl === 1 ? ' Stufe' : ' Stufen') + ' (' + meterText(s.meter) + ' m).';
    else if (s.aktion === 'etage') s.text = 'Nimm ' + (s.mittel === 'fahrstuhl' ? 'den Fahrstuhl' : 'die Treppe') + ' in Etage ' + s.nach_etage + '.';
    else s.text = s.seite ? 'Das Ziel (' + zl + ') liegt ' + seiteText[s.seite] + '.' : 'Du hast das Ziel (' + zl + ') erreicht.';
  });

  return {
    ok: true,
    start: info(start),
    ziel: info(target),
    gesamt_m: Math.round(es.reduce((s, e) => s + e.w, 0) * 100) / 100,
    stufen_gesamt: es.reduce((s, e) => s + e.stufen, 0),
    barrierefrei: bf,
    schritte: steps,
    text: steps.map(s => s.nr + '. ' + s.text).join('\n'),
    pfad: P.map(n => ({ id: n.id, name: label(n), typ: n.typ, haus: n.haus, etage: n.etage, x: n.x, y: n.y }))
  };

  function info(n) { return { id: n.id, name: label(n), typ: n.typ, haus: n.haus, etage: n.etage }; }
  // höchstens 3 Orientierungspunkte pro Abschnitt (Anfang, Mitte, Ende)
  function pick(l) { return l.length <= 3 ? l : [l[0], l[Math.floor((l.length - 1) / 2)], l[l.length - 1]]; }
}

const c = $('Eingabe vorbereiten').first().json;
const input = $input.first().json;
// Ein Code-Tool kann technische Fehler als Beobachtung liefern. Nicht als
// erfolgreichen Agentenlauf mit möglicherweise erfundenen Zielen behandeln.
for (const step of input.intermediateSteps || []) {
  const observation = typeof step.observation === 'string' ? step.observation : JSON.stringify(step.observation || '');
  if (observation.includes('RAUMWISSEN_NACH_3_VERSUCHEN') || observation.startsWith('There was an error:'))
    throw new Error('RAUMWISSEN_NACH_3_VERSUCHEN');
}
function output(result, httpStatus = 200) {
  return [{ json: { quelle: c.quelle, sessionId: c.sessionId, httpStatus, ...result } }];
}
function fail(fehler, hinweis, httpStatus = 422) {
  if (httpStatus >= 500) throw new Error(fehler);
  return output({ ok: false, status: 'fehler', fehler, hinweis }, httpStatus);
}
if (input.error) return fail('agent_fehler', 'Die KI-Anfrage konnte nicht verarbeitet werden. Bitte Zugangsdaten und Modell im n8n-Editor prüfen oder die Frage erneut stellen.', 502);
let a = input.output;
try {
  if (typeof a === 'string') {
    const t = a.replace(/```(?:json)?/gi, '');
    const i = t.indexOf('{'), j = t.lastIndexOf('}');
    a = JSON.parse(i >= 0 && j > i ? t.slice(i, j + 1) : t.trim());
  }
} catch (_) { return fail('agent_format', 'Die KI hat kein gültiges Antwortformat geliefert. Bitte erneut versuchen.', 502); }
if (!a || typeof a !== 'object' || Array.isArray(a)) return fail('agent_format', 'Die KI hat keine auswertbaren Zieldaten geliefert.', 502);
for (const key of ['aktion', 'ziel_id', 'ziel_raum', 'ziel_typ', 'start_id', 'antwort']) {
  if (a[key] === null || a[key] === undefined) a[key] = '';
  else if (typeof a[key] === 'number') a[key] = String(a[key]);
  if (typeof a[key] !== 'string') return fail('agent_format', 'Die KI-Antwort enthält ungültige Zieldaten.', 502);
  a[key] = a[key].trim();
}
if (a.aktion === 'rueckfrage' || a.aktion === 'info') {
  return output({ ok: false, status: a.aktion, text: a.antwort || 'Bitte nenne ein Ziel, zum Beispiel Raum 03.25 oder eine Toilette.' });
}
if (a.aktion !== 'route') return fail('agent_format', 'Die KI hat keine gültige Aktion geliefert.', 502);
// Synonyme sind Fachwissen aus der eingebetteten Datei, keine Chat-Erinnerungen.
const syn = c.synonyme || {};
const begriff = norm(a.ziel_raum || a.ziel_id);
if (['dekanat', 'prufungsamt', 'pruefungsamt'].includes(begriff)) {
  return output({ ok: false, status: 'rueckfrage', text: 'Welches ' + (begriff === 'dekanat' ? 'Dekanat (WI oder GW)' : 'Prüfungsamt beziehungsweise welches Büro') + ' meinst du?' });
}
if (Object.prototype.hasOwnProperty.call(syn.nicht_eindeutig || {}, begriff)) {
  const ids = syn.nicht_eindeutig[begriff];
  const alternativen = (syn.ziele || []).filter(e => ids.includes(e.raumcode))
    .map(e => e.bezeichnung + ' (' + e.raumcode + ')');
  return output({ ok: false, status: 'rueckfrage', text: 'Bitte präzisiere das Ziel „' + (a.ziel_raum || a.ziel_id)
    + '“. Die Bezeichnung ist in den Raumdaten als mehrdeutig markiert.'
    + (alternativen.length ? ' Mögliche Zuordnungen: ' + [...new Set(alternativen)].join('; ') + '.' : '') });
}
if (a.ziel_raum) {
  const eintraege = (syn.ziele || []).filter(e => e.namen.some(name => norm(name) === begriff));
  const codes = [...new Set(eintraege.map(e => e.raumcode))];
  if (codes.length > 1) return output({ ok: false, status: 'rueckfrage', text: 'Dieser Name gehört zu mehreren Räumen. Bitte nenne die vollständige Bezeichnung oder Raumnummer.' });
  if (codes.length === 1) {
    const ids = [...new Set(eintraege.flatMap(e => e.knoten_ids))];
    for (const e of eintraege) for (const id of e.knoten_ids) NAMEN.set(id, e.bezeichnung);
    if (/^\d{2}\.\d{2}\.\d{2}$/.test(codes[0])) a.ziel_raum = codes[0];
    else if (ids.length === 1) { a.ziel_id = ids[0]; a.ziel_raum = ''; }
    else return output({ ok: false, status: 'rueckfrage', text: 'Bitte nenne einen eindeutigen Zielknoten.' });
  } else {
    const fehlt = (syn.ohne_knoten || []).find(e => norm(e.name) === begriff || norm(e.raumnummer) === begriff);
    if (fehlt) return output({ ok: false, status: 'info', text: fehlt.name + ' ist als ' + fehlt.raumnummer
      + ' verzeichnet, aber nicht über diese Karte erreichbar: ' + fehlt.grund + '.' });
  }
}

const targets = ['ziel_id', 'ziel_raum', 'ziel_typ'].filter(k => a[k]);
if (targets.length !== 1) return fail('ziel_uneindeutig', 'Bitte nenne genau ein Ziel für die Wegberechnung.');
const nodes = new Map(GRAPH.knoten.map(n => [n.id, n]));
if (a.ziel_id && !nodes.has(a.ziel_id)) return fail('ziel_unbekannt', 'Das Ziel ist im Plan nicht vorhanden.');
if (a.ziel_typ && !['toilette', 'fahrstuhl', 'treppe', 'eingang', 'hoersaal'].includes(a.ziel_typ))
  return fail('ziel_unbekannt', 'Für diesen Zieltyp sind keine passenden Daten hinterlegt.');
const q = { ziel_id: a.ziel_id, ziel_raum: a.ziel_raum, ziel_typ: a.ziel_typ };
let startQuelle;
if (c.kontext.start_id) {
  q.start_id = c.kontext.start_id;
  startQuelle = 'kontext_start_id';
} else if (c.kontext.x !== null && c.kontext.y !== null) {
  Object.assign(q, { x: c.kontext.x, y: c.kontext.y, etage: c.kontext.etage, haus: c.kontext.haus });
  startQuelle = 'kontext_position';
} else if (a.start_id) {
  if (!nodes.has(a.start_id)) return fail('start_unbekannt', 'Der in der Frage genannte Startpunkt ist im Plan nicht vorhanden.');
  q.start_id = a.start_id;
  startQuelle = 'frage_oder_chatverlauf';
} else {
  q.start_id = c.config.testStartId;
  startQuelle = 'standard_eingang';
}
if (q.start_id && !nodes.has(q.start_id)) return fail('start_unbekannt', 'Der konfigurierte Standardstart ist im Plan nicht vorhanden.');
const result = route(GRAPH, q);
result.status = result.ok ? 'route' : 'fehler';
result.start_quelle = startQuelle;
result.hinweise = [];
if (startQuelle === 'standard_eingang') result.hinweise.push('Ohne Startangabe wird ab dem konfigurierten Eingang (' + c.config.testStartId + ') gerechnet.');
if (result.ok && (!result.pfad || !result.pfad.length)) {
  const s = nodes.get(result.start.id);
  result.pfad = [{ id: s.id, name: result.start.name, typ: s.typ, haus: s.haus, etage: s.etage, x: s.x, y: s.y }];
}
if (result.ok && startQuelle === 'kontext_position') {
