  if (!ziele.has(key)) ziele.set(key, { id: n.id, knoten_ids: [], typ: n.typ, haus: n.haus, etage: n.etage,
    raumcode: n.typ === 'raum' && /^\d{2}\.\d{2}\.\d{2}/.test(n.id) ? basis(n.id) : null,
    namen: [], bezeichnungen: [], kategorien: [] });
  const z = ziele.get(key);
  z.knoten_ids.push(n.id);
  for (const [field, map] of [['namen', namen], ['bezeichnungen', bezeichnungen], ['kategorien', kategorien]])
