// Kompaktkatalog: eine Zeile pro Ziel
function kompakt(k){
  const L=[];
  L.push('DATENSTAND: '+k.datenstand);
  L.push('HAEUSER: '+k.haeuser.join(', ')+' | ETAGEN: '+k.etagen.map(e=>e.haus+'.'+e.etage).join(', '));
  L.push('ZIELE (Format: ziel_id | typ | Haus.Etage | Kategorie | Namen):');
  for(const z of k.ziele){
    const namen=[...new Set((z.namen||[]).filter(n=>!/^(Büro|Buero) /.test(n)||z.namen.length<=2))];
    const alle=[...new Set([...(z.bezeichnungen||[]),...namen])];
    const ids=z.knoten_ids&&z.knoten_ids.length>1?' [Türen: '+z.knoten_ids.join(', ')+']':'';
    L.push([z.raumcode||z.id,z.typ,z.haus+'.'+z.etage,(z.kategorien||[]).join('/'),alle.join('; ')+ids].join(' | '));
  }
  L.push('NICHT_EINDEUTIG (nachfragen): '+Object.entries(k.nicht_eindeutig||{}).map(([a,b])=>a+' -> '+b.join('/')).join('; '));
  L.push('AUSSERHALB_DES_GRAPHEN (nur info, keine Route): '+(k.ausserhalb_des_graphen||[]).map(o=>o.name+' ('+o.raumnummer+', '+o.grund+')').join('; '));
  if((k.namenshinweise||[]).length) L.push('NAMENSHINWEISE: '+k.namenshinweise.map(h=>h.raumcode+' '+h.bezeichnung+': '+h.hinweis).join(' || '));
  L.push('HINWEIS: '+k.hinweis);
  return L.join('\n');
}

const katalog = kompakt(wissen);
return [{ json: { ...c, katalog } }];

